/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_insert` AFTER INSERT ON `tb_people` FOR EACH ROW BEGIN
  INSERT INTO `tb_logs` (`table_name`,`operation`,`db_user`,`description`,`operation_date`,`operation_status`)
  VALUES ('tb_people','Create',USER(),
          CONCAT('Persona creada. ID=',NEW.person_ID,', user_ID=',NEW.user_ID,
                 ', nombre=',NEW.given_names,' ',NEW.family_names,
                 ', género=',NEW.gender),
          CURRENT_TIMESTAMP,b'1');
END */;;
