/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_update` AFTER UPDATE ON `tb_people` FOR EACH ROW BEGIN
  DECLARE v_cambios TEXT DEFAULT '';
  IF NOT (OLD.user_ID <=> NEW.user_ID) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('user_ID: [',OLD.user_ID,'] -> [',NEW.user_ID,']')); END IF;
  IF NOT (OLD.courtesy_title_ID <=> NEW.courtesy_title_ID) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('courtesy_title_ID: [',COALESCE(OLD.courtesy_title_ID,'NULL'),'] -> [',COALESCE(NEW.courtesy_title_ID,'NULL'),']')); END IF;
  IF NOT (OLD.given_names <=> NEW.given_names) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('given_names: [',OLD.given_names,'] -> [',NEW.given_names,']')); END IF;
  IF NOT (OLD.family_names <=> NEW.family_names) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('family_names: [',OLD.family_names,'] -> [',NEW.family_names,']')); END IF;
  IF NOT (OLD.birth_date <=> NEW.birth_date) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('birth_date: [',COALESCE(CAST(OLD.birth_date AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.birth_date AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.gender <=> NEW.gender) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('gender: [',OLD.gender,'] -> [',NEW.gender,']')); END IF;
  IF NOT (OLD.country_code <=> NEW.country_code) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('country_code: [',COALESCE(OLD.country_code,'NULL'),'] -> [',COALESCE(NEW.country_code,'NULL'),']')); END IF;
  IF NOT (OLD.phone <=> NEW.phone) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('phone: [',COALESCE(OLD.phone,'NULL'),'] -> [',COALESCE(NEW.phone,'NULL'),']')); END IF;
  IF NOT (OLD.status <=> NEW.status) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('status: [',CAST(OLD.status AS UNSIGNED),'] -> [',CAST(NEW.status AS UNSIGNED),']')); END IF;
  IF v_cambios <> '' THEN
    INSERT INTO `tb_logs` (`table_name`,`operation`,`db_user`,`description`,`operation_date`,`operation_status`)
    VALUES ('tb_people','Update',USER(),CONCAT('Persona actualizada. ID=',NEW.person_ID,'. Cambios: ',v_cambios),CURRENT_TIMESTAMP,b'1');
  END IF;
END */;;
DELIMITER ;
