DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_register_user`(
    -- Datos de cuenta (tb_users)
    IN  p_email             VARCHAR(80),
    IN  p_nickname          VARCHAR(100),
    IN  p_password          VARCHAR(255),
    -- Datos personales (tb_people)
    IN  p_courtesy_title_ID CHAR(1),
    IN  p_given_names       VARCHAR(150),
    IN  p_family_names      VARCHAR(150),
    IN  p_birth_date        DATE,
    IN  p_gender            ENUM('Masculino','Femenino','Prefiero no decirlo'),
    IN  p_country_code      CHAR(2),
    IN  p_phone             VARCHAR(25),
    -- Salidas
    OUT p_user_ID           INT UNSIGNED,
    OUT p_person_ID         BIGINT UNSIGNED
)
    MODIFIES SQL DATA
BEGIN
    DECLARE v_email    VARCHAR(80)  DEFAULT LOWER(TRIM(p_email));
    DECLARE v_nickname VARCHAR(100) DEFAULT TRIM(p_nickname);
    DECLARE v_gender   ENUM('Masculino','Femenino','Prefiero no decirlo');

    -- Manejo de excepciones: Deshace cambios si ocurre algún error
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    -- Ajuste por defecto para el género
    SET v_gender = COALESCE(p_gender, 'Prefiero no decirlo');

    -- ---------- Validaciones de Cuenta ----------
    IF v_email IS NULL OR v_email = '' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El correo electrónico es obligatorio.';
    END IF;

    IF v_email NOT REGEXP '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El correo electrónico no tiene un formato válido.';
    END IF;

    IF v_nickname IS NULL OR v_nickname = '' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El nickname es obligatorio.';
    END IF;

    IF p_password IS NULL OR CHAR_LENGTH(p_password) < 8 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La contraseña debe tener al menos 8 caracteres.';
    END IF;

    -- ---------- Validaciones Personales ----------
    IF p_given_names IS NULL OR TRIM(p_given_names) = '' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El nombre es obligatorio.';
    END IF;

    IF p_family_names IS NULL OR TRIM(p_family_names) = '' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Los apellidos son obligatorios.';
    END IF;

    IF p_birth_date IS NOT NULL AND p_birth_date > CURRENT_DATE() THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La fecha de nacimiento no puede ser futura.';
    END IF;

    -- ---------- Validaciones de Duplicados ----------
    IF EXISTS (SELECT 1 FROM tb_users WHERE email = v_email) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El correo electrónico ya está registrado.';
    END IF;

    IF EXISTS (SELECT 1 FROM tb_users WHERE nickname = v_nickname) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El nickname ya está en uso.';
    END IF;

    -- ---------- Registro Transaccional ----------
    START TRANSACTION;

    -- 1) Inserción en tb_users (con MD5)
    INSERT INTO tb_users (
        email, 
        nickname, 
        password
    ) VALUES (
        v_email, 
        v_nickname, 
        MD5(p_password)
    );

    SET p_user_ID = LAST_INSERT_ID();

    -- 2) Inserción en tb_people
    INSERT INTO tb_people (
        user_ID, 
        courtesy_title_ID, 
        given_names, 
        family_names,
        birth_date, 
        gender, 
        country_code, 
        phone
    ) VALUES (
        p_user_ID,
        NULLIF(TRIM(p_courtesy_title_ID), ''),
        TRIM(p_given_names),
        TRIM(p_family_names),
        p_birth_date,
        v_gender,
        NULLIF(UPPER(TRIM(p_country_code)), ''),
        NULLIF(TRIM(p_phone), '')
    );

    SET p_person_ID = LAST_INSERT_ID();

    COMMIT;
END ;;
DELIMITER ;
