    IN p_category_id INT UNSIGNED,
    IN p_product_id INT UNSIGNED
)
BEGIN
    UPDATE tbd_products_categories
    SET status = b'0'
    WHERE category_ID = p_category_id
      AND product_ID = p_product_id
      AND status = b'1';
END ;;
DELIMITER ;
